      kind: "phase",
      label: "digest",
      span: { first: slice[0]!.id, last: slice.at(-1)!.id, ts_first: slice[0]!.ts, ts_last: slice.at(-1)!.ts },
      event_ids: slice.map((e) => e.id),
      children: [],
      stats: { events: slice.length, tool_calls: 0, input_tokens: 0, output_tokens: 0 },
